To solve this problem, we need to create an algorithm that calculates the sum of the digits and the difference between the sum of the squares of the digits and the sum of the digits for each number from 1 to 2000, and then checks if these two numbers are relatively prime.

We can implement this algorithm using Python code as follows:

```python
import math

def is_relatively_prime(a, b):
    if a == b:
        return False
    for i in range(2, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            return False
    return True

def sum_of_digits(n):
    return sum(int(digit) for digit in str(n))

def sum_of_squares_of_digits(n):
    return sum(int(digit) ** 2 for digit in str(n))

def difference(n):
    return sum_of_squares_of_digits(n) - sum_of_digits(n)

count = 0
for i in range(1, 2001):
    sum_of_digits_i = sum_of_digits(i)
    difference_i = difference(i)
    if is_relatively_prime(sum_of_digits_i, difference_i):
        count += 1

print(count)
```

